import base64,gzip,sys,pathlib
S='[... ELLIPSIZATION ...]'
src=gzip.decompress(base64.b64decode(S)).decode('utf-8')
# Persist readable source next to derived output when --out is present.
try:
    oi=sys.argv.index('--out')+1
    out=pathlib.Path(sys.argv[oi]); out.mkdir(parents=True,exist_ok=True); (out/'analysis_code.py').write_text(src,encoding='utf-8')
except Exception: pass
exec(compile(src,'analysis_code.py','exec'),globals(),globals())
